    long long cdx = dx, cdy = dy;

    for (long long i = 0; i < t; ++i) {
        long long k = (x + y) + i; // bushes at step i (0-based)
        cdx += k;
        cdy += k;
        x = ((x + cdx - 1) % n + n) % n + 1;
        y = ((y + cdy - 1) % n + n) % n + 1;
    }

    cout << x << " " << y << endl;
